/**
 * frontend/scripts/analytics-codegen.ts
 *
 * Part 8.3 Analytics Codegen Engine — Walks the registry and generates:
 * 1. src/analytics/generated/element-ids.ts (TypeScript union type of every valid ID)
 * 2. docs/analytics-taxonomy.md (Complete auto-generated documentation)
 * 3. src/analytics/generated/ga4-custom-dimensions.csv (GA4 Admin CSV import)
 * 4. src/analytics/generated/analytics-manifest.json (QA + CI manifest)
 *
 * Run via: npm run analytics:build
 */

import * as fs from 'fs';
import * as path from 'path';

const rootDir = process.cwd();
const idsFilePath = path.join(rootDir, 'src/analytics/constants/ids.ts');
const generatedDir = path.join(rootDir, 'src/analytics/generated');
const docsPath = path.join(rootDir, '../docs/analytics-taxonomy.md');

function extractIds(content: string): string[] {
  const matches = content.match(/'sa\.[a-z0-9.-]+'/g) || [];
  return Array.from(new Set(matches.map((m) => m.replace(/'/g, ''))));
}

function runCodegen() {
  console.log('🚀 Running Analytics Codegen Engine...');

  if (!fs.existsSync(generatedDir)) {
    fs.mkdirSync(generatedDir, { recursive: true });
  }

  const idsContent = fs.readFileSync(idsFilePath, 'utf-8');
  const allIds = extractIds(idsContent);

  // 1. Emit element-ids.ts
  const elementIdsTs = `/**
 * Auto-generated by scripts/analytics-codegen.ts — DO NOT EDIT MANUALLY
 */

export type ElementIdString =\n${allIds.map((id) => `  | '${id}'`).join('\n')};\n
export const ALL_ELEMENT_IDS: ElementIdString[] = [\n${allIds.map((id) => `  '${id}',`).join('\n')}\n];
`;
  fs.writeFileSync(path.join(generatedDir, 'element-ids.ts'), elementIdsTs, 'utf-8');
  console.log(`  ✓ Generated src/analytics/generated/element-ids.ts (${allIds.length} IDs)`);

  // 2. Emit analytics-manifest.json
  const manifest = {
    generatedAt: new Date().toISOString(),
    totalElements: allIds.length,
    elements: allIds.map((id) => {
      const parts = id.split('.');
      return {
        id,
        surface: parts[1] || 'global',
        area: parts[2] || 'general',
        type: parts[3] || 'btn',
      };
    }),
  };
  fs.writeFileSync(path.join(generatedDir, 'analytics-manifest.json'), JSON.stringify(manifest, null, 2), 'utf-8');
  console.log(`  ✓ Generated src/analytics/generated/analytics-manifest.json`);

  // 3. Emit ga4-custom-dimensions.csv
  const csvLines = [
    'Dimension Name,Scope,Event Parameter / User Property,Description',
    'Element ID,Event,element_id,Unique identifier of the clicked/viewed UI element',
    'Element Type,Event,element_type,Type of element (btn/card/link/tab/chip)',
    'Surface,Event,surface,Product surface (echo/agentk/student/mentor/marketing)',
    'Area,Event,area,Page section or feature area',
    'Screen Name,Event,screen,Current screen name',
    'Breakpoint,Event,breakpoint,Responsive viewport breakpoint (xs/sm/md/lg/xl)',
    'Flow ID,Event,flow_id,Funnel flow identifier',
    'Flow Step Name,Event,flow_step_name,Name of funnel step',
    'User Role,User,user_role,Role of user (student/alumni/mentor/college/admin)',
    'Organization ID,User,org_id,Associated college or group ID',
  ];
  fs.writeFileSync(path.join(generatedDir, 'ga4-custom-dimensions.csv'), csvLines.join('\n'), 'utf-8');
  console.log(`  ✓ Generated src/analytics/generated/ga4-custom-dimensions.csv`);

  // 4. Emit docs/analytics-taxonomy.md
  let markdown = `# StudentAlumni.ai — Analytics Taxonomy & Element ID Registry\n\n`;
  markdown += `*Auto-generated from \`src/analytics/constants/ids.ts\` by \`scripts/analytics-codegen.ts\`.*\n\n`;
  markdown += `Total Registered Elements: **${allIds.length}**\n\n`;

  markdown += `## Registered Element IDs\n\n`;
  markdown += `| Element ID | Surface | Area | Type |\n`;
  markdown += `|---|---|---|---|\n`;

  for (const id of allIds) {
    const parts = id.split('.');
    const surface = parts[1] || 'global';
    const area = parts[2] || 'general';
    const type = parts[3] || 'btn';
    markdown += `| \`${id}\` | ${surface} | ${area} | \`${type}\` |\n`;
  }

  markdown += `\n## GA4 Custom Dimensions Reference\n\n`;
  markdown += `| Dimension Name | Scope | Parameter | Notes |\n`;
  markdown += `|---|---|---|---|\n`;
  markdown += `| \`element_id\` | Event | \`element_id\` | Registered canonical element ID |\n`;
  markdown += `| \`element_type\` | Event | \`element_type\` | Derived from ID |\n`;
  markdown += `| \`surface\` | Event | \`surface\` | Derived surface |\n`;
  markdown += `| \`area\` | Event | \`area\` | Derived area |\n`;
  markdown += `| \`user_role\` | User | \`user_role\` | Role of user |\n`;
  markdown += `| \`org_id\` | User | \`org_id\` | College/Campus ID |\n`;

  fs.mkdirSync(path.dirname(docsPath), { recursive: true });
  fs.writeFileSync(docsPath, markdown, 'utf-8');
  console.log(`  ✓ Generated docs/analytics-taxonomy.md`);

  console.log('✨ Codegen build completed successfully!');
}

runCodegen();
